#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
constexpr ll MOD =998244353;

int n;
vector<vector<int>> idx;

bool check(int x,int L,int R, int pos)
{
    for(int i:idx[x])
    {
        bool pre=false,suf=false;
        if(pos<=i)
        {
            int cp=min(i,L)+ max(0,i-(n-R));
            pre=(cp==(i+1)/2);
        }
        if(!pre && pos>=i)
        {
            int cs= max(0,L-i+1)+(n+1-max(i,n-R+1));
            suf=(cs==(n-i+2)/2);
        }
        if(!pre && !suf)
            return false;
    }
    return true;
}

int main()
{
    int t;
    cin>>t;
    while(t--)
    {
        cin>>n;
        idx.assign(n+1,{});
        bool bad = false;
        
        for(int i=1;i<=n; i++)
        {
            int a;
            cin>>a;
            if(a<1 || a>n) bad=true;
            else idx[a].push_back(i);
        }
        if(bad)
        {
            cout<<0<<endl;
            continue;
        }
        
        vector<ll> dp(n+2,0),ndp(n+2,0);
        dp[0]=1;
        
        for(int x=1;x<=n;x++)
        {
            fill(ndp.begin(),ndp.end(),0);
            
            for(int L=0;L<=x-1;L++)
            {
                if(!dp[L]) continue;
                int R=x-1-L;
                
                if(check(x,L+1,R,L+1))
                    ndp[L+1]=(ndp[L+1] + dp[L])%MOD;
                    
                if(x<n && check(x,L,R+1,n-R))
                    ndp[L]=(ndp[L]+dp[L])%MOD;
            }
            
            swap(dp,ndp);
        }
        ll ans=0;
        for(int L=0;L<=n;L++)
            ans=(ans+dp[L])%MOD;
        
        cout<<ans<<endl;
    }
}
